# -*- coding: utf-8 -*-
# 7-turkce-15 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="760" height="300" fill="#f8fafc" rx="12"/>\n  <text x="380" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">METNİN BÖLÜMLERİ VE BÖLÜMLER ARASI BAĞLANTI</text>\n  <rect x="30" y="48" width="210" height="145" rx="10" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="135" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">GİRİŞ</text>\n  <text x="45" y="96" font-size="11" fill="#334155">• Konuyu tanıtır</text>\n  <text x="45" y="116" font-size="11" fill="#334155">• Okurun ilgisini çeker</text>\n  <text x="45" y="136" font-size="11" fill="#334155">• Ana düşünceyi hazırlar</text>\n  <text x="135" y="176" text-anchor="middle" font-size="10" font-style="italic" fill="#1e40af">öncelikle, her şeyden önce</text>\n  <line x1="240" y1="120" x2="266" y2="120" stroke="#64748b" stroke-width="2"/>\n  <polygon points="264,113 275,120 264,127" fill="#64748b"/>\n  <rect x="275" y="48" width="210" height="145" rx="10" fill="#fefce8" stroke="#eab308"/>\n  <text x="380" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#a16207">GELİŞME</text>\n  <text x="290" y="96" font-size="11" fill="#334155">• Ana düşünceyi açar</text>\n  <text x="290" y="116" font-size="11" fill="#334155">• Örnek, tanık, karşılaştırma</text>\n  <text x="290" y="136" font-size="11" fill="#334155">• Sonuç için kanıt toplar</text>\n  <text x="380" y="176" text-anchor="middle" font-size="10" font-style="italic" fill="#a16207">örneğin, ayrıca, öte yandan</text>\n  <line x1="485" y1="120" x2="511" y2="120" stroke="#64748b" stroke-width="2"/>\n  <polygon points="509,113 520,120 509,127" fill="#64748b"/>\n  <rect x="520" y="48" width="210" height="145" rx="10" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="625" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">SONUÇ</text>\n  <text x="535" y="96" font-size="11" fill="#334155">• Düşünceyi yargıya bağlar</text>\n  <text x="535" y="116" font-size="11" fill="#334155">• Öğüt ya da çağrı yapar</text>\n  <text x="535" y="136" font-size="11" fill="#334155">• Girişi yankılayarak kapanır</text>\n  <text x="625" y="176" text-anchor="middle" font-size="10" font-style="italic" fill="#15803d">sonuç olarak, kısacası, öyleyse</text>\n  <rect x="30" y="210" width="700" height="72" rx="10" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="380" y="232" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">Öyküleyici metinde: SERİM (kişi, yer, zaman) → DÜĞÜM (sorun, merak) → ÇÖZÜM (sonuçlanma)</text>\n  <text x="380" y="254" text-anchor="middle" font-size="11" fill="#334155">Eskici örneği: Filistin\'e gönderiliş → kimseyle anlaşamayıp suskunlaşma → eskiciyle sevinç ve ayrılık</text>\n  <text x="380" y="273" text-anchor="middle" font-size="10" fill="#9d174d">Her bölüm bir sonrakini hazırlar; biri eksik olursa metin yarım kalır.</text>\n</svg>', 'b2': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="760" height="300" fill="#f8fafc" rx="12"/>\n  <text x="380" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİNLEDİĞİMİZ METİNLERDE İKNA ETME TEKNİKLERİ</text>\n  <rect x="30" y="46" width="225" height="76" rx="10" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="142" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kanıt ve Sayısal Veri</text>\n  <text x="142" y="94" text-anchor="middle" font-size="11" fill="#334155">anket, oran, araştırma</text>\n  <text x="142" y="112" text-anchor="middle" font-size="10" fill="#1e40af">AKLA SESLENİR</text>\n  <rect x="267" y="46" width="225" height="76" rx="10" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="379" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Güvenilir Kaynak</text>\n  <text x="379" y="94" text-anchor="middle" font-size="11" fill="#334155">uzman, bilim insanı, yazar</text>\n  <text x="379" y="112" text-anchor="middle" font-size="10" fill="#1e40af">AKLA SESLENİR</text>\n  <rect x="504" y="46" width="225" height="76" rx="10" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="616" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Örnek ve Yaşanmış Olay</text>\n  <text x="616" y="94" text-anchor="middle" font-size="11" fill="#334155">somut durum, kısa anı</text>\n  <text x="616" y="112" text-anchor="middle" font-size="10" fill="#1e40af">AKLA VE GÖNLE SESLENİR</text>\n  <rect x="30" y="134" width="225" height="76" rx="10" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="142" y="160" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Duygulara Seslenme</text>\n  <text x="142" y="182" text-anchor="middle" font-size="11" fill="#334155">sevgi, üzüntü, vicdan</text>\n  <text x="142" y="200" text-anchor="middle" font-size="10" fill="#9d174d">GÖNLE SESLENİR</text>\n  <rect x="267" y="134" width="225" height="76" rx="10" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="379" y="160" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Cevabı Belli Soru</text>\n  <text x="379" y="182" text-anchor="middle" font-size="11" fill="#334155">Kim kırılmak ister ki?</text>\n  <text x="379" y="200" text-anchor="middle" font-size="10" fill="#9d174d">DÜŞÜNDÜRÜR</text>\n  <rect x="504" y="134" width="225" height="76" rx="10" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="616" y="160" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Ortak Değerler</text>\n  <text x="616" y="182" text-anchor="middle" font-size="11" fill="#334155">atasözü, hadis, büyük sözü</text>\n  <text x="616" y="200" text-anchor="middle" font-size="10" fill="#9d174d">GÖNLE SESLENİR</text>\n  <rect x="30" y="222" width="345" height="62" rx="10" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="202" y="246" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">GÜÇLÜ İKNA</text>\n  <text x="202" y="268" text-anchor="middle" font-size="11" fill="#334155">Kanıt + güvenilir kaynak + duygu birlikte</text>\n  <rect x="385" y="222" width="345" height="62" rx="10" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="557" y="246" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">ZAYIF İKNA (DİKKAT!)</text>\n  <text x="557" y="268" text-anchor="middle" font-size="11" fill="#334155">Herkes böyle yapıyor / korku abartısı</text>\n</svg>', 'b3': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="760" height="300" fill="#f8fafc" rx="12"/>\n  <text x="380" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DEĞERLENDİRME VE ELEŞTİRİ BASAMAKLARI</text>\n  <text x="30" y="50" font-size="12" font-weight="bold" fill="#1d4ed8">DEĞERLENDİRME (4 adım)</text>\n  <rect x="30" y="60" width="158" height="80" rx="10" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="109" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Norm Belirle</text>\n  <text x="109" y="110" text-anchor="middle" font-size="11" fill="#334155">Ölçütü seç</text>\n  <text x="109" y="127" text-anchor="middle" font-size="10" fill="#64748b">kanıt, süre, nezaket</text>\n  <polygon points="193,93 207,100 193,107" fill="#64748b"/>\n  <rect x="212" y="60" width="158" height="80" rx="10" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="291" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. İncele</text>\n  <text x="291" y="110" text-anchor="middle" font-size="11" fill="#334155">Bulguları topla</text>\n  <text x="291" y="127" text-anchor="middle" font-size="10" fill="#64748b">say, not al, işaretle</text>\n  <polygon points="375,93 389,100 375,107" fill="#64748b"/>\n  <rect x="394" y="60" width="158" height="80" rx="10" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="473" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">3. Karşılaştır</text>\n  <text x="473" y="110" text-anchor="middle" font-size="11" fill="#334155">Bulgu ile normu</text>\n  <text x="473" y="127" text-anchor="middle" font-size="10" fill="#64748b">yan yana koy</text>\n  <polygon points="557,93 571,100 557,107" fill="#64748b"/>\n  <rect x="576" y="60" width="158" height="80" rx="10" fill="#dbeafe" stroke="#1d4ed8"/>\n  <text x="655" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">4. Yargıya Var</text>\n  <text x="655" y="110" text-anchor="middle" font-size="11" fill="#334155">Başarılı mı?</text>\n  <text x="655" y="127" text-anchor="middle" font-size="10" fill="#64748b">gerekçesiyle söyle</text>\n  <text x="30" y="172" font-size="12" font-weight="bold" fill="#a16207">ELEŞTİRİ (3 adım)</text>\n  <rect x="30" y="182" width="215" height="80" rx="10" fill="#fefce8" stroke="#eab308"/>\n  <text x="137" y="210" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Sorgula</text>\n  <text x="137" y="232" text-anchor="middle" font-size="11" fill="#334155">Bir özelliği seç ve sor</text>\n  <polygon points="250,215 264,222 250,229" fill="#64748b"/>\n  <rect x="272" y="182" width="215" height="80" rx="10" fill="#fefce8" stroke="#eab308"/>\n  <text x="379" y="210" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Akıl Yürüt</text>\n  <text x="379" y="232" text-anchor="middle" font-size="11" fill="#334155">Olumlu / olumsuz yargı</text>\n  <polygon points="492,215 506,222 492,229" fill="#64748b"/>\n  <rect x="514" y="182" width="220" height="80" rx="10" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="624" y="210" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. Alternatif Üret</text>\n  <text x="624" y="232" text-anchor="middle" font-size="11" fill="#334155">Gerekçeli öneri sun</text>\n  <text x="380" y="287" text-anchor="middle" font-size="11" font-weight="bold" fill="#334155">Kişiyi değil ürünü konuş: kusuru göster, çözümü de sun.</text>\n</svg>', 'b4': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="760" height="300" fill="#f8fafc" rx="12"/>\n  <text x="380" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÖZET HUNİSİ: METİNDEN KENDİ CÜMLELERİMİZE</text>\n  <polygon points="40,48 340,48 250,200 130,200" fill="#eff6ff" stroke="#3b82f6" stroke-width="2"/>\n  <text x="190" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">METNİN TAMAMI</text>\n  <text x="190" y="98" text-anchor="middle" font-size="11" fill="#334155">1. Çözümle: Her cümle ne işe yarıyor?</text>\n  <text x="190" y="126" text-anchor="middle" font-size="11" fill="#334155">2. Sınıflandır:</text>\n  <text x="190" y="142" text-anchor="middle" font-size="11" fill="#334155">önemli / önemsiz</text>\n  <text x="190" y="172" text-anchor="middle" font-size="11" fill="#334155">3. Sırala</text>\n  <rect x="120" y="212" width="140" height="64" rx="10" fill="#dbeafe" stroke="#1d4ed8"/>\n  <text x="190" y="238" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">4. ÖZET</text>\n  <text x="190" y="258" text-anchor="middle" font-size="10" fill="#334155">kendi cümlelerinle</text>\n  <polygon points="184,202 196,202 190,210" fill="#1d4ed8"/>\n  <rect x="370" y="48" width="175" height="170" rx="10" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="457" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">ELENENLER</text>\n  <text x="385" y="98" font-size="11" fill="#334155">• Uzun betimlemeler</text>\n  <text x="385" y="120" font-size="11" fill="#334155">• Tekrarlar</text>\n  <text x="385" y="142" font-size="11" fill="#334155">• Ayrıntılı örnekler</text>\n  <text x="385" y="164" font-size="11" fill="#334155">• Tanık sözleri</text>\n  <text x="385" y="186" font-size="11" fill="#334155">• Kişisel yorum</text>\n  <rect x="560" y="48" width="175" height="170" rx="10" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="647" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">KALANLAR</text>\n  <text x="575" y="98" font-size="11" fill="#334155">• Konu</text>\n  <text x="575" y="120" font-size="11" fill="#334155">• Ana düşünce</text>\n  <text x="575" y="142" font-size="11" fill="#334155">• Temel olaylar</text>\n  <text x="575" y="164" font-size="11" fill="#334155">• Sonuç yargısı</text>\n  <text x="575" y="186" font-size="11" fill="#334155">• Öğüt / ileti</text>\n  <rect x="370" y="230" width="365" height="50" rx="10" fill="#fefce8" stroke="#eab308"/>\n  <text x="552" y="251" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">Sözlü özet: Açılış → Gövde (sırayla) → Kapanış</text>\n  <text x="552" y="269" text-anchor="middle" font-size="10" fill="#334155">Notta yalnız anahtar kelimeler; ezber yok, göz teması var.</text>\n</svg>', 'b5': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="760" height="300" fill="#f8fafc" rx="12"/>\n  <text x="380" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZLÜ TARTIŞMA: TEMELLENDİR, TESPİT ET, ETKİLİ SUN</text>\n  <rect x="25" y="44" width="230" height="240" rx="10" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="140" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Mantıklı Temellendirme</text>\n  <rect x="45" y="80" width="190" height="46" rx="8" fill="#ffffff" stroke="#3b82f6"/>\n  <text x="140" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">İDDİA</text>\n  <text x="140" y="117" text-anchor="middle" font-size="10" fill="#334155">Ne savunuyorum?</text>\n  <polygon points="134,130 146,130 140,140" fill="#3b82f6"/>\n  <rect x="45" y="144" width="190" height="46" rx="8" fill="#ffffff" stroke="#3b82f6"/>\n  <text x="140" y="164" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">GEREKÇE</text>\n  <text x="140" y="181" text-anchor="middle" font-size="10" fill="#334155">Çünkü...</text>\n  <polygon points="134,194 146,194 140,204" fill="#3b82f6"/>\n  <rect x="45" y="208" width="190" height="46" rx="8" fill="#ffffff" stroke="#3b82f6"/>\n  <text x="140" y="228" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">KANIT</text>\n  <text x="140" y="245" text-anchor="middle" font-size="10" fill="#334155">örnek, veri, tanık</text>\n  <rect x="265" y="44" width="230" height="240" rx="10" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="380" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Tutarsızlık Avı</text>\n  <text x="280" y="94" font-size="11" fill="#334155">• Aşırı genelleme</text>\n  <text x="292" y="110" font-size="10" fill="#64748b">herkes, hiç kimse, hep</text>\n  <text x="280" y="134" font-size="11" fill="#334155">• Kişiye saldırı</text>\n  <text x="280" y="158" font-size="11" fill="#334155">• Kendisiyle çelişme</text>\n  <text x="280" y="182" font-size="11" fill="#334155">• Konu dışına çıkma</text>\n  <text x="280" y="206" font-size="11" fill="#334155">• Doğrulanmamış bilgi</text>\n  <text x="380" y="244" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Çürüt: kanıtla ve nazikçe</text>\n  <text x="380" y="262" text-anchor="middle" font-size="10" fill="#334155">Doğru görüşü kabul et.</text>\n  <rect x="505" y="44" width="230" height="240" rx="10" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="620" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Beden Dili ve Mekân</text>\n  <text x="520" y="94" font-size="11" fill="#334155">✓ Salonun her yanına göz teması</text>\n  <text x="520" y="118" font-size="11" fill="#334155">✓ Dik, rahat duruş</text>\n  <text x="520" y="142" font-size="11" fill="#334155">✓ Açık eller, kavuşmamış kollar</text>\n  <text x="520" y="166" font-size="11" fill="#334155">✓ Söze uygun yüz ifadesi</text>\n  <text x="520" y="190" font-size="11" fill="#334155">✓ Salona göre ses ayarı</text>\n  <text x="520" y="214" font-size="11" fill="#334155">✓ Çember / U oturma düzeni</text>\n  <text x="620" y="252" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Selam → Söz al/ver → Teşekkür</text>\n</svg>', 'b6': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="760" height="300" fill="#f8fafc" rx="12"/>\n  <text x="380" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KARŞILAŞTIRMA YAZISI VE YAZIM KURALLARI</text>\n  <circle cx="200" cy="150" r="105" fill="#3b82f6" fill-opacity="0.15" stroke="#3b82f6" stroke-width="2"/>\n  <circle cx="330" cy="150" r="105" fill="#ec4899" fill-opacity="0.15" stroke="#ec4899" stroke-width="2"/>\n  <text x="150" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">YÜZ YÜZE</text>\n  <text x="150" y="124" text-anchor="middle" font-size="11" fill="#334155">Beden dili</text>\n  <text x="150" y="146" text-anchor="middle" font-size="11" fill="#334155">Ses tonu</text>\n  <text x="150" y="168" text-anchor="middle" font-size="11" fill="#334155">Anında yanıt</text>\n  <text x="265" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#7c3aed">ORTAK</text>\n  <text x="265" y="124" text-anchor="middle" font-size="11" fill="#334155">Nezaket</text>\n  <text x="265" y="146" text-anchor="middle" font-size="11" fill="#334155">Saygı</text>\n  <text x="265" y="168" text-anchor="middle" font-size="11" fill="#334155">Anlaşma</text>\n  <text x="380" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">DİJİTAL</text>\n  <text x="380" y="124" text-anchor="middle" font-size="11" fill="#334155">Yazı, simge</text>\n  <text x="380" y="146" text-anchor="middle" font-size="11" fill="#334155">Kalıcı kayıt</text>\n  <text x="380" y="168" text-anchor="middle" font-size="11" fill="#334155">Gecikmeli yanıt</text>\n  <text x="265" y="284" text-anchor="middle" font-size="11" font-weight="bold" fill="#334155">Yargı: Ortam değişse de nezaket değişmez.</text>\n  <rect x="470" y="44" width="265" height="240" rx="10" fill="#fefce8" stroke="#eab308"/>\n  <text x="602" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Yazım ve Noktalama</text>\n  <text x="484" y="92" font-size="11" fill="#334155">• Bağlaç de ayrı: Sen de gel.</text>\n  <text x="484" y="114" font-size="11" fill="#334155">• Ek -de bitişik: Sınıfta kaldı.</text>\n  <text x="484" y="136" font-size="11" fill="#334155">• Bağlaç ki ayrı: Duydum ki...</text>\n  <text x="484" y="158" font-size="11" fill="#334155">• Ek -ki bitişik: evdeki, yarınki</text>\n  <text x="484" y="180" font-size="11" fill="#334155">• Soru eki ayrı: Geldin mi?</text>\n  <text x="484" y="202" font-size="11" fill="#334155">• Sonraki ek bitişik: Hazır mısın?</text>\n  <text x="484" y="224" font-size="11" fill="#334155">• Hitaptan sonra virgül:</text>\n  <text x="496" y="242" font-size="11" fill="#334155">Sevgili arkadaşlar, ...</text>\n  <text x="602" y="270" text-anchor="middle" font-size="10" font-weight="bold" fill="#a16207">Çıkarma testi: de çıkınca cümle bozulmuyorsa bağlaçtır.</text>\n</svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
